  // --- RiskTab ---
  "homeRental.risk.scoreExplainPrefix": { id: "Customer Risk Score dihitung dari kelengkapan identitas, verifikasi alamat/WA, dan riwayat sewa (telat, no-show, aset rusak/hilang) — bukan data rekening bank. Booking dari nomor kategori ", en: "The Customer Risk Score is calculated from identity completeness, address/WhatsApp verification, and rental history (late returns, no-shows, damaged/missing assets) — not bank account data. Bookings from customers in the ", ms: "Skor Risiko Pelanggan dikira daripada kelengkapan identiti, pengesahan alamat/WA, dan sejarah sewa (lewat, tidak hadir, aset rosak/hilang) — bukan data akaun bank. Tempahan daripada nombor kategori ", th: "คะแนนความเสี่ยงลูกค้าคำนวณจากความครบถ้วนของข้อมูลประจำตัว การยืนยันที่อยู่/WA และประวัติการเช่า (คืนช้า ไม่มาตามนัด ทรัพย์สินเสียหาย/สูญหาย) — ไม่ใช่ข้อมูลบัญชีธนาคาร การจองจากหมายเลขในหมวดหมู่ ", fil: "Ang Customer Risk Score ay kinakalkula mula sa kumpleto ng pagkakakilanlan, pag-verify ng address/WA, at history ng rental (huli, no-show, sirang/nawawalang asset) — hindi data ng bank account. Ang booking mula sa numerong kategorya ", vi: "Điểm rủi ro khách hàng được tính từ mức độ đầy đủ của giấy tờ tùy thân, xác minh địa chỉ/WA, và lịch sử thuê (trả trễ, không đến, tài sản hư/mất) — không phải dữ liệu tài khoản ngân hàng. Đặt chỗ từ số điện thoại thuộc nhóm " },
  "homeRental.risk.riskWord": { id: "Risiko", en: "Risk", ms: "Risiko", th: "ความเสี่ยง", fil: "Risk", vi: "Rủi ro" },
  "homeRental.risk.tolakWord": { id: "Tolak", en: "Reject", ms: "Tolak", th: "ปฏิเสธ", fil: "Tanggihan", vi: "Từ chối" },
  "homeRental.risk.scoreExplainSuffix": { id: " menunggu approval Owner/Manager sebelum Checkout.", en: " wait for Owner/Manager approval before Checkout.", ms: " menunggu kelulusan Pemilik/Pengurus sebelum Checkout.", th: " ต้องรอการอนุมัติจากเจ้าของ/ผู้จัดการก่อนทำ Checkout", fil: " ay naghihintay ng approval ng Owner/Manager bago mag-Checkout.", vi: " sẽ chờ Chủ sở hữu/Quản lý phê duyệt trước khi Checkout." },
  "homeRental.risk.privacyNote": { id: "Data ini bank data risiko/fraud lintas-outlet seluruh merchant NEXBILL se-Indonesia — tapi untuk menjaga privasi, tidak ditampilkan sebagai daftar. Cari No. HP/Nama/No. KTP untuk melihat SATU customer yang dituju. Ubah/blacklist hanya bisa untuk data milik outlet sendiri.", en: "This is a shared cross-outlet risk/fraud data bank across all NEXBILL merchants in Indonesia — but to protect privacy, it's never shown as a browsable list. Search by Phone/Name/ID Number to view ONE specific customer. Editing/blacklisting only works for data owned by your own outlet.", ms: "Data ini adalah bank data risiko/fraud rentas-outlet bagi semua peniaga NEXBILL di seluruh Indonesia — tetapi untuk menjaga privasi, ia tidak dipaparkan sebagai senarai. Cari No. Telefon/Nama/No. Kad Pengenalan untuk melihat SATU pelanggan yang dituju. Ubah/senarai hitam hanya boleh untuk data milik outlet sendiri.", th: "ข้อมูลนี้เป็นฐานข้อมูลความเสี่ยง/การฉ้อโกงข้ามสาขาของร้านค้า NEXBILL ทั่วอินโดนีเซีย — แต่เพื่อความเป็นส่วนตัว จะไม่แสดงเป็นรายการ ให้ค้นหาด้วยเบอร์โทร/ชื่อ/เลขบัตรประชาชนเพื่อดูลูกค้าเพียงรายเดียวที่ต้องการ การแก้ไข/ขึ้นบัญชีดำทำได้เฉพาะข้อมูลของสาขาตนเองเท่านั้น", fil: "Ang data na ito ay isang shared cross-outlet risk/fraud data bank sa lahat ng NEXBILL merchant sa buong Indonesia — pero para protektahan ang privacy, hindi ito ipinapakita bilang listahan. Maghanap gamit ang Phone/Pangalan/ID Number para makita ang ISANG customer na target. Ang pag-edit/blacklist ay para lang sa data na pag-aari ng sarili mong outlet.", vi: "Đây là kho dữ liệu rủi ro/gian lận dùng chung giữa các chi nhánh của toàn bộ đối tác NEXBILL trên khắp Indonesia — nhưng để bảo vệ quyền riêng tư, dữ liệu không hiển thị dưới dạng danh sách. Tìm theo Số điện thoại/Tên/Số CMND để xem MỘT khách hàng cụ thể. Chỉ có thể chỉnh sửa/đưa vào danh sách đen đối với dữ liệu thuộc chi nhánh của bạn." },
  "homeRental.risk.searchPlaceholder": { id: "Cari No. HP / Nama / No. KTP untuk melihat 1 customer...", en: "Search Phone / Name / ID Number to view 1 customer...", ms: "Cari No. Telefon / Nama / No. Kad Pengenalan untuk melihat 1 pelanggan...", th: "ค้นหาเบอร์โทร / ชื่อ / เลขบัตรประชาชนเพื่อดูลูกค้า 1 ราย...", fil: "Maghanap ng Phone / Pangalan / ID Number para makita ang 1 customer...", vi: "Tìm Số điện thoại / Tên / Số CMND để xem 1 khách hàng..." },
