  // --- PolicyRuleSection (generic) ---
  "homeRental.policy.labelRequired": { id: "Label wajib diisi.", en: "Label is required.", ms: "Label wajib diisi.", th: "ต้องกรอกป้ายกำกับ", fil: "Kinakailangan ang label.", vi: "Bắt buộc nhập nhãn." },
  "homeRental.policy.confirmDelete": { id: "Hapus aturan ini? Kalau cuma mau nonaktifkan sementara, matikan toggle Aktif saja.", en: "Delete this rule? If you just want to temporarily disable it, turn off the Active toggle instead.", ms: "Padam peraturan ini? Jika hanya mahu nyahaktifkan sementara, matikan togol Aktif sahaja.", th: "ลบกฎนี้หรือไม่? หากต้องการปิดใช้งานชั่วคราวเท่านั้น ให้ปิดสวิตช์ใช้งานแทน", fil: "Burahin ang panuntunang ito? Kung gusto mo lang i-disable pansamantala, i-off na lang ang Active toggle.", vi: "Xóa quy tắc này? Nếu chỉ muốn tạm tắt, hãy tắt công tắc Đang hoạt động thay vào đó." },
  "homeRental.policy.noRules": { id: "Belum ada aturan.", en: "No rules yet.", ms: "Belum ada peraturan.", th: "ยังไม่มีกฎ", fil: "Wala pang panuntunan.", vi: "Chưa có quy tắc nào." },
  "homeRental.policy.extraDayCheckbox": { id: "1 hari tambahan", en: "1 extra day", ms: "1 hari tambahan", th: "เพิ่ม 1 วัน", fil: "1 karagdagang araw", vi: "Thêm 1 ngày" },
